#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
using Kamilunavo.RepairEmpire.Gameplay;
using Kamilunavo.RepairEmpire.Core;
using Kamilunavo.RepairEmpire.Input;
using Kamilunavo.RepairEmpire.UI;
namespace Kamilunavo.RepairEmpire.QA {
 public sealed class RepairRuntimeQa:MonoBehaviour {
  RepairGame game;string output,mode;int passes,errors;readonly List<float> frames=new();
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void StartQa(){if(!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("REPAIR_QA_MODE")))new GameObject("RepairRuntimeQA").AddComponent<RepairRuntimeQa>();}
  void Awake(){mode=Environment.GetEnvironmentVariable("REPAIR_QA_MODE");output=Environment.GetEnvironmentVariable("REPAIR_QA_OUTPUT")??Path.Combine(Application.persistentDataPath,"RepairQA");Directory.CreateDirectory(output);Application.logMessageReceived+=Log;Application.runInBackground=true;}
  void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert){errors++;File.AppendAllText(Path.Combine(output,"errors.txt"),text+"\n"+stack+"\n");}}
  void Check(bool value,string title){if(!value)throw new Exception("REPAIR_QA_FAIL "+title);passes++;Debug.Log("REPAIR_QA_PASS "+title);File.AppendAllText(Path.Combine(output,"checks.txt"),title+"\n");}
  IEnumerator Start(){yield return new WaitForSecondsRealtime(2);game=FindFirstObjectByType<RepairGame>();var routine=Run();while(true){bool next;try{next=routine.MoveNext();}catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"FAIL.txt"),e.ToString());yield break;}if(!next)break;yield return routine.Current;}}
  IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(output,name+".png"));yield return null;}
  HoldButton FindHold(string name)=>GameObject.Find(name)?.GetComponent<HoldButton>();
  void Held(HoldButton hold,bool value){Check(hold!=null,"Actual hold exists "+(hold!=null?hold.name:"missing"));if(value)ExecuteEvents.Execute(hold.gameObject,new PointerEventData(EventSystem.current),ExecuteEvents.pointerDownHandler);else ExecuteEvents.Execute(hold.gameObject,new PointerEventData(EventSystem.current),ExecuteEvents.pointerUpHandler);}
  void SetHeld(HoldButton hold,bool value){if(hold.Held==value)return;if(value)hold.OnPointerDown(new PointerEventData(EventSystem.current));else hold.OnPointerUp(new PointerEventData(EventSystem.current));}
  void Press(string name){var go=GameObject.Find(name);Check(go!=null,"Actual UI exists "+name);var button=go.GetComponent<Button>();Check(button!=null&&button.interactable,"Actual UI enabled "+name);var point=UiMetrics.ScreenRect((RectTransform)go.transform).center;var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=point},hits);Check(hits.Count>0&&(hits[0].gameObject==go||hits[0].gameObject.transform.IsChildOf(go.transform)),"Actual touch raycast "+name);ExecuteEvents.Execute(go,new PointerEventData(EventSystem.current){position=point},ExecuteEvents.pointerClickHandler);}
  void Sizes(){Canvas.ForceUpdateCanvases();float scale=UiMetrics.PointScale;foreach(var b in game.Hud.GetComponentsInChildren<Selectable>()){if(!b.gameObject.activeInHierarchy)continue;var r=UiMetrics.ScreenRect((RectTransform)b.transform);Check(r.width/scale>=47.999f&&r.height/scale>=47.999f,"48 point target "+b.name);if(b.GetComponent<HoldButton>()!=null){Rect view=UnityEngine.Camera.main.pixelRect;Check(view.Contains(r.min+Vector2.one)&&view.Contains(r.max-Vector2.one),"Hold control inside usable region "+b.name);}}}
  IEnumerator Run(){Check(game!=null&&game.Vehicle!=null&&game.Hud!=null,"Production boot");Check(Resources.Load<Texture2D>("Art/RepairAtlas")!=null&&Resources.Load<Texture2D>("Art/SkyPanorama")!=null,"Actual Texture2D assets");if(mode=="reload"){Check(game.Profile.CompletedJobs>=4,"Fresh process restores completed calls");Check(game.Profile.CompletedTicket>0&&game.Profile.ActiveTicket==0,"Fresh process preserves paid-ticket frontier");Check(game.Profile.Cash>=0&&game.Profile.ToolMask==7,"Fresh process restores company economy");yield return Capture("reload");Finish();yield break;}
   Check(game.Profile.CompletedJobs==0&&game.Profile.Cash==1130&&game.Profile.Level==2,"Isolated fresh company baseline");yield return Capture("home");Sizes();game.Hud.ShowPage(0);yield return null;Press("AcceptSelected");Check(!game.Paused&&game.ActiveJob!=null,"Actual tablet accepts selected service call");var gas=game.Vehicle.Accelerate;Held(gas,true);float startZ=game.Vehicle.transform.position.z;yield return new WaitForSecondsRealtime(2);Check(game.Vehicle.transform.position.z>startZ+8&&game.Vehicle.SpeedKmh>10,"Actual Rigidbody touch acceleration");game.Hud.ShowPage(0);yield return new WaitForFixedUpdate();Check(!gas.Held&&game.Vehicle.SpeedKmh<.01f,"Tablet stops actual van and clears held gas");var stop=game.Vehicle.transform.position;yield return new WaitForSecondsRealtime(.4f);Check(Vector3.Distance(stop,game.Vehicle.transform.position)<.01f,"Actual paused Rigidbody remains stationary");Sizes();var scroll=game.Hud.GetComponentInChildren<ScrollRect>();Check(scroll!=null&&scroll.viewport.GetComponent<Image>().raycastTarget,"Actual scroll viewport accepts touches");scroll.verticalNormalizedPosition=0;yield return null;Check(scroll.content.anchoredPosition.y>100,"Actual 24-call list scrolls to last row");yield return Capture("jobs-bottom");game.Hud.Close();
   for(int i=0;i<8;i++){game.Hud.ShowPage(i);yield return null;Sizes();yield return Capture("tablet-de-"+i);game.Hud.Close();}game.Transact(p=>{p.Language="en";return true;});for(int i=0;i<8;i++){game.Hud.ShowPage(i);yield return null;Sizes();yield return Capture("tablet-en-"+i);game.Hud.Close();}game.Transact(p=>{p.Language="de";return true;});
   string[] ids={"faucet","switch","call-2-0","call-3-0"};for(int k=0;k<ids.Length;k++){if(k==1)Check(game.Transact(p=>RepairRules.BuyTool(p,1)),"Earned level unlocks actual voltage tool");if(k==2)Check(game.Transact(p=>RepairRules.BuyTool(p,2)),"Earned level unlocks actual professional kit");var job=JobCatalog.Find(ids[k]);Check(game.SelectJob(job),"Accept category "+job.CategoryIndex);game.ReturnToWorkshop();yield return new WaitForSecondsRealtime(.5f);gas=game.Vehicle.Accelerate;Held(gas,true);float until=Time.realtimeSinceStartup+45;while(Time.realtimeSinceStartup<until){float v=game.Vehicle.SpeedKmh/3.6f;float lead=v*v/(2*game.Vehicle.BrakeForce)+1;if(game.Vehicle.transform.position.z>=job.DestinationZ-lead)break;float target=Mathf.Atan2(job.DestinationX-game.Vehicle.transform.position.x,Mathf.Max(12,v))*Mathf.Rad2Deg;float turn=Mathf.DeltaAngle(game.Vehicle.transform.eulerAngles.y,target);SetHeld(game.Vehicle.Left,turn< -1);SetHeld(game.Vehicle.Right,turn>1);yield return new WaitForFixedUpdate();}SetHeld(game.Vehicle.Left,false);SetHeld(game.Vehicle.Right,false);Held(gas,false);Check(game.Vehicle.transform.position.z>=job.DestinationZ-12,"Drive actual route category "+job.CategoryIndex);var brake=game.Vehicle.Brake;Held(brake,true);until=Time.realtimeSinceStartup+4;while(game.Vehicle.SpeedKmh>1&&Time.realtimeSinceStartup<until)yield return new WaitForFixedUpdate();Held(brake,false);yield return new WaitForFixedUpdate();Debug.Log("REPAIR_QA_ARRIVAL "+job.Id+" pos="+game.Vehicle.transform.position+" speed="+game.Vehicle.SpeedKmh+" distance="+game.Distance);Check(game.BeginRepair(),"Stopped actual van enters category repair "+job.CategoryIndex);yield return null;int cash=game.Profile.Cash;long ticket=game.Profile.ActiveTicket;int completions=game.Profile.CompletedJobs;Check(!game.AdvanceRepair(2)&&game.Profile.RepairPhase==0,"Cannot skip first stage "+job.CategoryIndex);var hold=FindHold("RepairHold");Held(hold,true);yield return new WaitForSecondsRealtime(.3f);Held(hold,false);Check(game.Profile.RepairPhase==0,"Partial hold grants no phase "+job.CategoryIndex);Held(hold,true);until=Time.realtimeSinceStartup+3;while(game.Profile.RepairPhase==0&&Time.realtimeSinceStartup<until)yield return null;Check(game.Profile.RepairPhase==1,"Actual hold completes isolation "+job.CategoryIndex);yield return null;Press("RepairTap2");Check(game.Interaction.Taps==0,"Out of order contact resets "+job.CategoryIndex);for(int tap=0;tap<4;tap++){Press("RepairTap"+tap);yield return null;}Check(game.Profile.RepairPhase==2,"Actual four touch contacts persist phase "+job.CategoryIndex);yield return Capture("repair-category-"+job.CategoryIndex);hold=FindHold("RepairHold");Held(hold,true);until=Time.realtimeSinceStartup+3;while(game.RepairOpen&&Time.realtimeSinceStartup<until)yield return null;Check(!game.RepairOpen&&game.Profile.CompletedJobs==completions+1&&game.Profile.CompletedTicket==ticket&&game.Profile.Cash==cash+job.Reward,"Actual tested repair pays once "+job.CategoryIndex);Check(!game.AdvanceRepair(2)&&game.Profile.Cash==cash+job.Reward,"Paid repair rejects duplicate callback "+job.CategoryIndex);Check(Mathf.Abs(game.Vehicle.transform.position.z-job.DestinationZ)<6,"Completed repair remains at customer "+job.CategoryIndex);}
   int earnedCash=game.Profile.Cash;Check(game.Transact(p=>RepairRules.ClaimDailyJobs(p,DateTime.UtcNow)>0)&&game.Profile.Cash==earnedCash+250,"Actual three-call daily bonus");Check(!game.Transact(p=>RepairRules.ClaimDailyJobs(p,DateTime.UtcNow)>0),"Daily bonus refuses replay");yield return Poses();int before=game.Profile.Cash;game.Vehicle.transform.position=new Vector3(90,-8,500);yield return null;yield return new WaitForFixedUpdate();Check(game.Vehicle.transform.position.y>-.1f&&Mathf.Abs(game.Vehicle.transform.position.x)<=32&&game.Vehicle.transform.position.z<=435,"Actual out of bounds recovery");Check(game.Profile.Cash==before&&game.Profile.CompletedJobs==4,"Recovery preserves earned company");Check(game.Save(),"Actual atomic company saved");yield return Capture("finished");
   if(mode=="soak"){double begin=Time.realtimeSinceStartupAsDouble;long memory=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),peak=memory;int capture=0;game.ReturnToWorkshop();SetHeld(game.Vehicle.Accelerate,true);bool stopping=false;int laps=0;while(Time.realtimeSinceStartupAsDouble-begin<1800){if(game.Vehicle.transform.position.z>410&&!stopping){SetHeld(game.Vehicle.Accelerate,false);SetHeld(game.Vehicle.Brake,true);stopping=true;}if(stopping&&game.Vehicle.SpeedKmh<1){SetHeld(game.Vehicle.Brake,false);game.ReturnToWorkshop();SetHeld(game.Vehicle.Accelerate,true);stopping=false;laps++;}float turn=Mathf.DeltaAngle(game.Vehicle.transform.eulerAngles.y,Mathf.Atan2(-game.Vehicle.transform.position.x,18)*Mathf.Rad2Deg);SetHeld(game.Vehicle.Left,turn< -1);SetHeld(game.Vehicle.Right,turn>1);frames.Add(Time.unscaledDeltaTime*1000);peak=Math.Max(peak,UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong());if(Time.realtimeSinceStartupAsDouble-begin>=capture*60){yield return Capture("soak-"+capture++);}yield return null;}game.Vehicle.ResetMotion();Check(laps>20,"Real soak includes repeated actual driving laps "+laps);game.Save();frames.Sort();File.WriteAllText(Path.Combine(output,"soak.json"),"{\"elapsedSeconds\":"+(Time.realtimeSinceStartupAsDouble-begin).ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"frames\":"+frames.Count+",\"p95ms\":"+frames[(int)(frames.Count*.95)].ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"startMemory\":"+memory+",\"endMemory\":"+UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()+",\"peakMemory\":"+peak+",\"errors\":"+errors+"}");Check(errors==0,"Real 1800 second soak has no errors");}Finish();}
  IEnumerator Poses(){Screen.orientation=ScreenOrientation.LandscapeLeft;
#if !UNITY_IOS && !UNITY_ANDROID
   Screen.SetResolution(852,393,false);
#endif
   yield return new WaitForSecondsRealtime(1);Check(Screen.width>Screen.height,"Actual landscape render settled");Sizes();yield return Capture("landscape-home");game.Hud.ShowPage(0);yield return null;Sizes();yield return Capture("landscape-tablet");game.Hud.Close();ReservedRegionProvider.QaDivision=new Rect(.48f,0,.04f,1);yield return new WaitForSecondsRealtime(.4f);Sizes();Check(UnityEngine.Camera.main.rect.xMax<=.481f||UnityEngine.Camera.main.rect.xMin>=.519f,"Camera avoids synthetic reserved region");yield return Capture("reserved-pane");ReservedRegionProvider.QaDivision=null;Screen.orientation=ScreenOrientation.Portrait;
#if !UNITY_IOS && !UNITY_ANDROID
   Screen.SetResolution(393,852,false);
#endif
   yield return new WaitForSecondsRealtime(1);Check(Screen.width<Screen.height,"Actual portrait render restored");Sizes();}
  void Finish(){Check(errors==0,"No runtime exceptions");File.WriteAllText(Path.Combine(output,"PASS.txt"),"REPAIR_RUNTIME_PASS "+passes);Debug.Log("REPAIR_RUNTIME_PASS "+passes);}
 }
}
#endif
